 String readSecret(String name){try{return readEncrypted(name);}catch(Exception e){return "";}}
 javax.crypto.SecretKey getStorageKey() throws Exception {java.security.KeyStore ks=java.security.KeyStore.getInstance("AndroidKeyStore");ks.load(null);String alias="mondi_device_storage_v1";if(ks.containsAlias(alias))return (javax.crypto.SecretKey)ks.getKey(alias,null);javax.crypto.KeyGenerator kg=javax.crypto.KeyGenerator.getInstance("AES","AndroidKeyStore");kg.init(new android.security.keystore.KeyGenParameterSpec.Builder(alias,android.security.keystore.KeyProperties.PURPOSE_ENCRYPT|android.security.keystore.KeyProperties.PURPOSE_DECRYPT).setBlockModes("GCM").setEncryptionPaddings("NoPadding").setRandomizedEncryptionRequired(true).build());return kg.generateKey();}
 void saveSecret(String name,String value)throws Exception{javax.crypto.Cipher cipher=javax.crypto.Cipher.getInstance("AES/GCM/NoPadding");cipher.init(javax.crypto.Cipher.ENCRYPT_MODE,getStorageKey());byte[] encrypted=cipher.doFinal(value.getBytes("UTF-8"));String blob=android.util.Base64.encodeToString(cipher.getIV(),android.util.Base64.NO_WRAP)+":"+android.util.Base64.encodeToString(encrypted,android.util.Base64.NO_WRAP);getPreferences(0).edit().putString("secure_"+name,blob).apply();}
 String readEncrypted(String name)throws Exception{String blob=getPreferences(0).getString("secure_"+name,"");if(blob.isEmpty())return "";String[] parts=blob.split(":",2);javax.crypto.Cipher cipher=javax.crypto.Cipher.getInstance("AES/GCM/NoPadding");cipher.init(javax.crypto.Cipher.DECRYPT_MODE,getStorageKey(),new javax.crypto.spec.GCMParameterSpec(128,android.util.Base64.decode(parts[0],android.util.Base64.NO_WRAP)));return new String(cipher.doFinal(android.util.Base64.decode(parts[1],android.util.Base64.NO_WRAP)),"UTF-8");}
