 void showSearchEngines(){String q=input.getText().toString().trim();if(q.isEmpty()){toast("Escribe lo que quieres buscar primero.");return;}String[] engines={"Google","Bing","DuckDuckGo","Brave","Ecosia","Tor Browser (si está instalado)"};new AlertDialog.Builder(this).setTitle("Buscar con").setItems(engines,(d,i)->{String query=Uri.encode(q);String[] urls={"https://www.google.com/search?q="+query,"https://www.bing.com/search?q="+query,"https://duckduckgo.com/?q="+query,"https://search.brave.com/search?q="+query,"https://www.ecosia.org/search?q="+query,"https://duckduckgo.com/?q="+query};Intent intent=new Intent(Intent.ACTION_VIEW,Uri.parse(urls[i]));if(i==5)intent.setPackage("org.torproject.torbrowser");try{startActivity(intent);}catch(ActivityNotFoundException e){toast("Tor Browser no está instalado. Instálalo desde su fuente oficial para usar Tor.");}}).show();}
