 void calculator(){EditText expression=new EditText(this);expression.setSingleLine(true);expression.setHint("Ejemplo: (12 + 8) * 3 / 2");new AlertDialog.Builder(this).setTitle("Calculadora MONDI").setView(expression).setPositiveButton("Calcular",(d,w)->{try{double result=new ArithmeticParser(expression.getText().toString()).parse();String value=(result==(long)result)?Long.toString((long)result):Double.toString(result);new AlertDialog.Builder(this).setTitle("Resultado").setMessage(value).setPositiveButton("Cerrar",null).show();}catch(Exception e){toast("Expresión no válida. Usa números, +, -, *, / y paréntesis.");}}).setNegativeButton("Cancelar",null).show();}
 static class ArithmeticParser{final String s;int p=0;ArithmeticParser(String s){this.s=s;}void spaces(){while(p<s.length()&&Character.isWhitespace(s.charAt(p)))p++;}double parse(){double v=sum();spaces();if(p!=s.length())throw new IllegalArgumentException();return v;}double sum(){double v=product();while(true){spaces();if(p<s.length()&&(s.charAt(p)=='+'||s.charAt(p)=='-')){char op=s.charAt(p++);double b=product();v=op=='+'?v+b:v-b;}else return v;}}double product(){double v=factor();while(true){spaces();if(p<s.length()&&(s.charAt(p)=='*'||s.charAt(p)=='/')){char op=s.charAt(p++);double b=factor();if(op=='/'&&b==0)throw new ArithmeticException();v=op=='*'?v*b:v/b;}else return v;}}double factor(){spaces();if(p<s.length()&&(s.charAt(p)=='+'||s.charAt(p)=='-'))return (s.charAt(p++)=='-'?-1:1)*factor();if(p<s.length()&&s.charAt(p)=='('){p++;double v=sum();spaces();if(p>=s.length()||s.charAt(p++)!=')')throw new IllegalArgumentException();return v;}int start=p;while(p<s.length()&&(Character.isDigit(s.charAt(p))||s.charAt(p)=='.'))p++;if(start==p)throw new IllegalArgumentException();return Double.parseDouble(s.substring(start,p));}}
 void showLevel(){android.hardware.SensorManager manager=(android.hardware.SensorManager)getSystemService(SENSOR_SERVICE);android.hardware.Sensor sensor=manager.getDefaultSensor(android.hardware.Sensor.TYPE_ACCELEROMETER);if(sensor==null){toast("Este móvil no informa de un acelerómetro.");return;}TextView reading=new TextView(this);reading.setTextSize(20);reading.setGravity(Gravity.CENTER);reading.setText("Coloca el móvil sobre la superficie");LevelView bubble=new LevelView();LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.addView(bubble,new LinearLayout.LayoutParams(-1,dp(220)));box.addView(reading);android.app.AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Nivel de burbuja").setView(box).setPositiveButton("Cerrar",null).create();android.hardware.SensorEventListener listener=new android.hardware.SensorEventListener(){public void onAccuracyChanged(android.hardware.Sensor s,int accuracy){}public void onSensorChanged(android.hardware.SensorEvent e){float x=e.values[0],y=e.values[1],z=e.values[2];double roll=Math.toDegrees(Math.atan2(y,z));double pitch=Math.toDegrees(Math.atan2(-x,Math.sqrt(y*y+z*z)));reading.setText(String.format(Locale.getDefault(),"Inclinación: %.1f°   ·   Giro: %.1f°",pitch,roll));bubble.setAngles(pitch,roll);}};dialog.setOnDismissListener(v->manager.unregisterListener(listener));dialog.show();manager.registerListener(listener,sensor,android.hardware.SensorManager.SENSOR_DELAY_UI);}
 class LevelView extends View{double pitch=0,roll=0;final android.graphics.Paint paint=new android.graphics.Paint(3);LevelView(){super(MainActivity.this);}void setAngles(double p,double r){pitch=p;roll=r;invalidate();}protected void onDraw(android.graphics.Canvas c){super.onDraw(c);float cx=getWidth()/2f,cy=getHeight()/2f,r=Math.min(getWidth(),getHeight())*.38f;paint.setColor(0xffd7e4ff);paint.setStyle(android.graphics.Paint.Style.STROKE);paint.setStrokeWidth(dp(2));c.drawCircle(cx,cy,r,paint);c.drawLine(cx-r,cy,cx+r,cy,paint);c.drawLine(cx,cy-r,cx,cy+r,paint);paint.setStyle(android.graphics.Paint.Style.FILL);paint.setColor(0xff21b8a6);float bx=cx+(float)(Math.max(-30,Math.min(30,roll))/30*r*.72),by=cy-(float)(Math.max(-30,Math.min(30,pitch))/30*r*.72);c.drawCircle(bx,by,dp(12),paint);}}

 void checkUpdates(){append("MONDI: Buscando la última versión estable…");new Thread(()->{HttpURLConnection c=null;try{URL u=new URL("https://api.github.com/repos/juanantoniomo/Mondi-ia-/releases?per_page=30");c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(15000);c.setRequestProperty("Accept","application/vnd.github+json");c.setRequestProperty("User-Agent","MONDI-AI-Android");if(c.getResponseCode()!=200)throw new IOException("GitHub HTTP "+c.getResponseCode());ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1&&out.size()<1000000)out.write(b,0,n);}JSONArray releases=new JSONArray(out.toString("UTF-8"));JSONObject asset=null,release=null;long installedCode;android.content.pm.PackageInfo current=getPackageManager().getPackageInfo(getPackageName(),0);installedCode=android.os.Build.VERSION.SDK_INT>=28?current.getLongVersionCode():current.versionCode;for(int i=0;i<releases.length();i++){JSONObject r=releases.getJSONObject(i);if(r.optBoolean("draft")||r.optBoolean("prerelease"))continue;JSONArray assets=r.optJSONArray("assets");if(assets==null)continue;for(int j=0;j<assets.length();j++){JSONObject a=assets.getJSONObject(j);if("app-release.apk".equalsIgnoreCase(a.optString("name"))&&a.optLong("size",0)>10000){String body=r.optString("body","");java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?i)versionCode\\s*[=:]\\s*(\\d+)").matcher(body);if(m.find()&&Long.parseLong(m.group(1))>installedCode){asset=a;release=r;break;}}}if(asset!=null)break;}if(asset==null){append("MONDI: Ya tienes la última versión estable publicada.");return;}JSONObject found=asset,rel=release;String version=rel.optString("name",rel.optString("tag_name","nueva versión"));runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Actualización MONDI AI").setMessage("Disponible: "+version+"\nInstalada: "+current.versionName+"\n\nSe descargará la APK y Android confirmará la instalación.").setPositiveButton("Actualizar",(d,w)->{if(android.os.Build.VERSION.SDK_INT>=26&&!getPackageManager().canRequestPackageInstalls()){getPreferences(0).edit().putBoolean("update_after_permission",true).apply();startActivityForResult(new Intent(android.provider.Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())),11);}else downloadAndInstall(found);}).setNegativeButton("Cerrar",null).show());}catch(Exception e){append("MONDI: No se pudo comprobar la actualización: "+e.getMessage());}finally{if(c!=null)c.disconnect();}}).start();}
 void downloadAndInstall(JSONObject asset){new Thread(()->{HttpURLConnection c=null;try{URL url=new URL(asset.getString("browser_download_url"));c=(HttpURLConnection)url.openConnection();c.setConnectTimeout(20000);c.setReadTimeout(30000);c.setInstanceFollowRedirects(true);c.setRequestProperty("User-Agent","MONDI-AI-Android");if(c.getResponseCode()!=200)throw new IOException("Descarga HTTP "+c.getResponseCode());long expected=c.getContentLengthLong();if(expected<=0||expected>100L*1024*1024)throw new IOException("Tamaño de APK no válido");java.io.File apk=new java.io.File(getCacheDir(),"mondi-update.apk");java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");try(InputStream in=c.getInputStream();FileOutputStream file=new FileOutputStream(apk)){byte[] b=new byte[8192];int n;long total=0;while((n=in.read(b))!=-1){total+=n;if(total>100L*1024*1024)throw new IOException("APK demasiado grande");file.write(b,0,n);digest.update(b,0,n);}}byte[] hash=digest.digest();String expectedDigest=asset.optString("digest","");if(expectedDigest.startsWith("sha256:")){String hex=expectedDigest.substring(7);StringBuilder got=new StringBuilder();for(byte x:hash)got.append(String.format(Locale.ROOT,"%02x",x));if(!got.toString().equalsIgnoreCase(hex))throw new IOException("La comprobación SHA-256 no coincide");}int signingFlag=android.os.Build.VERSION.SDK_INT>=28?android.content.pm.PackageManager.GET_SIGNING_CERTIFICATES:android.content.pm.PackageManager.GET_SIGNATURES;android.content.pm.PackageInfo candidate=getPackageManager().getPackageArchiveInfo(apk.getAbsolutePath(),signingFlag);if(candidate==null||!getPackageName().equals(candidate.packageName))throw new IOException("La APK no pertenece a MONDI AI");long newCode=android.os.Build.VERSION.SDK_INT>=28?candidate.getLongVersionCode():candidate.versionCode;android.content.pm.PackageInfo installed=getPackageManager().getPackageInfo(getPackageName(),signingFlag);long oldCode=android.os.Build.VERSION.SDK_INT>=28?installed.getLongVersionCode():installed.versionCode;if(newCode<=oldCode)throw new IOException("La APK publicada no tiene una versión superior");android.content.pm.Signature[] installedSigners=getSigners(installed),newSigners=getSigners(candidate);if(installedSigners.length!=newSigners.length)throw new IOException("La firma de esta APK cambió. Android requiere una reinstalación única antes de poder actualizar automáticamente.");for(android.content.pm.Signature s:installedSigners){boolean match=false;for(android.content.pm.Signature n:newSigners)if(s.equals(n)){match=true;break;}if(!match)throw new IOException("La firma de esta APK cambió. Android requiere una reinstalación única antes de poder actualizar automáticamente.");}android.content.pm.PackageInstaller installer=getPackageManager().getPackageInstaller();android.content.pm.PackageInstaller.SessionParams params=new android.content.pm.PackageInstaller.SessionParams(android.content.pm.PackageInstaller.SessionParams.MODE_FULL_INSTALL);params.setAppPackageName(getPackageName());int id=installer.createSession(params);try(android.content.pm.PackageInstaller.Session session=installer.openSession(id);InputStream in=new FileInputStream(apk)){try(OutputStream out=session.openWrite("mondi-update",0,apk.length())){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);session.fsync(out);}Intent statusIntent=new Intent(this,InstallStatusReceiver.class);statusIntent.setAction(getPackageName()+".UPDATE_STATUS");PendingIntent pending=PendingIntent.getBroadcast(this,0,statusIntent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);session.commit(pending.getIntentSender());}runOnUiThread(()->append("MONDI: APK verificada. Android abrirá la confirmación de instalación."));}catch(Exception e){runOnUiThread(()->append("MONDI: No se pudo instalar la actualización: "+e.getMessage()));}finally{if(c!=null)c.disconnect();}}).start();}
 android.content.pm.Signature[] getSigners(android.content.pm.PackageInfo info){if(android.os.Build.VERSION.SDK_INT>=28&&info.signingInfo!=null)return info.signingInfo.getApkContentsSigners();return info.signatures==null?new android.content.pm.Signature[0]:info.signatures;}
 void terminal(){final EditText command=new EditText(this);command.setHint("Comando Android: pwd, ls, id...");final TextView output=new TextView(this);output.setTextIsSelectable(true);output.setText("Terminal Android local. No es Ubuntu ni tiene root. Los comandos se ejecutan con los permisos de MONDI AI.");ScrollView sv=new ScrollView(this);sv.addView(output);LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(20,12,20,12);layout.addView(command);layout.addView(sv,new LinearLayout.LayoutParams(-1,400));new AlertDialog.Builder(this).setTitle("Terminal local").setView(layout).setPositiveButton("Ejecutar",(dialog,which)->{String cmd=command.getText().toString().trim();if(cmd.isEmpty())return;new Thread(()->{try{java.lang.Process process=new ProcessBuilder("/system/bin/sh","-c",cmd).redirectErrorStream(true).start();ByteArrayOutputStream out=new ByteArrayOutputStream();InputStream in=process.getInputStream();byte[] b=new byte[2048];int n,total=0;while((n=in.read(b))!=-1&&total<30000){int count=Math.min(n,30000-total);out.write(b,0,count);total+=count;}boolean finished=process.waitFor(15,java.util.concurrent.TimeUnit.SECONDS);if(!finished)process.destroyForcibly();int status=finished?process.exitValue():-1;String result=out.toString("UTF-8")+"\nCódigo de salida: "+status;runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Resultado del comando").setMessage(result).setPositiveButton("Cerrar",null).show());}catch(Exception e){runOnUiThread(()->toast(e.toString()));}}).start();}).setNegativeButton("Cancelar",null).show();}


 void codeEditor(){
 final File workspace=new File(getFilesDir(),"workspace");workspace.mkdirs();
 LinearLayout layout=new LinearLayout(this);layout.setOrientation(1);layout.setPadding(16,12,16,12);
 EditText filename=new EditText(this);filename.setSingleLine(true);filename.setHint("archivo.sh");filename.setText("hola.sh");layout.addView(filename);
 EditText source=new EditText(this);source.setGravity(Gravity.TOP);source.setMinLines(10);source.setText("#!/system/bin/sh\necho Hola desde MONDI AI\npwd\n");layout.addView(source,new LinearLayout.LayoutParams(-1,0,1));
 TextView info=new TextView(this);info.setText("Editor local: guarda archivos en el espacio privado de MONDI. Ejecutar solo admite scripts .sh con /system/bin/sh. No incluye Python, Node ni Ubuntu.");layout.addView(info);
 final AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Editor MONDI").setView(layout).setPositiveButton("Cerrar",null).create();
 LinearLayout controls=new LinearLayout(this);
 Button load=new Button(this);load.setText("Abrir");controls.addView(load,new LinearLayout.LayoutParams(0,-2,1));
 Button save=new Button(this);save.setText("Guardar");controls.addView(save,new LinearLayout.LayoutParams(0,-2,1));
 Button run=new Button(this);run.setText("Ejecutar .sh");controls.addView(run,new LinearLayout.LayoutParams(0,-2,1));
 layout.addView(controls);
 java.util.function.Supplier<File> selected=()->{
 String name=filename.getText().toString().trim();
 if(!name.matches("[A-Za-z0-9_.-]{1,80}")||name.startsWith(".")){toast("Nombre de archivo no válido");return null;}
 return new File(workspace,name);
 };
 load.setOnClickListener(v->{File f=selected.get();if(f==null)return;try{
 byte[] bytes=java.nio.file.Files.readAllBytes(f.toPath());if(bytes.length>100000){toast("Archivo demasiado grande");return;}
 source.setText(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));
 }catch(Exception e){toast("No se pudo abrir: "+e.getMessage());}});
 save.setOnClickListener(v->{File f=selected.get();if(f==null)return;try{
 java.nio.file.Files.write(f.toPath(),source.getText().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));toast("Guardado: "+f.getName());
 }catch(Exception e){toast("No se pudo guardar: "+e.getMessage());}});
 run.setOnClickListener(v->{File f=selected.get();if(f==null)return;if(!f.getName().endsWith(".sh")){toast("Solo scripts .sh");return;}
 new AlertDialog.Builder(this).setTitle("Confirmar ejecución").setMessage("Se ejecutará el código escrito usando el shell Android con permisos de MONDI AI. Ejecuta solo código que conozcas.")
 .setPositiveButton("Ejecutar",(d,w)->{try{java.nio.file.Files.write(f.toPath(),source.getText().toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}catch(Exception e){toast(e.getMessage());return;}
 new Thread(()->{try{
 java.lang.Process proc=new ProcessBuilder("/system/bin/sh",f.getAbsolutePath()).directory(workspace).redirectErrorStream(true).start();
 boolean finished=proc.waitFor(15,java.util.concurrent.TimeUnit.SECONDS);if(!finished)proc.destroyForcibly();
 ByteArrayOutputStream out=new ByteArrayOutputStream();InputStream in=proc.getInputStream();byte[] buf=new byte[2048];int n,total=0;
 while((n=in.read(buf))!=-1&&total<20000){int take=Math.min(n,20000-total);out.write(buf,0,take);total+=take;}
 String result=out.toString("UTF-8")+(finished?"\nSalida: "+proc.exitValue():"\nTiempo agotado");
 runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Resultado").setMessage(result).setPositiveButton("Cerrar",null).show());
 }catch(Exception e){runOnUiThread(()->toast(e.toString()));}}).start();
 }).setNegativeButton("Cancelar",null).show();
 });
 dialog.show();
 }

 void programmingToolkit(){
 String[] names={"Instalar herramientas Ubuntu","Python y pip","Git","Node.js","Compilar C","Utilidades Linux","Ejemplo Python","Ejemplo JavaScript","Ejemplo Bash","Flujo Git","Diagnóstico Android"};
 String[] scripts={"apt update && apt upgrade -y\napt install -y python3 python3-pip git curl wget nano vim build-essential","python3 --version\npython3 -m venv entorno\n. entorno/bin/activate\npython -m pip install --upgrade pip","git --version\ngit config --global user.name \"Tu nombre\"\ngit status","apt install -y nodejs npm\nnode --version\nnpm --version","apt install -y build-essential\nprintf '#include <stdio.h>\\nint main(){puts(\"Hola MONDI\");return 0;}\\n' > hola.c\ngcc hola.c -o hola\n./hola","apt install -y zip unzip jq openssh-client procps iproute2","print('Hola desde MONDI AI')\nfor i in range(3): print(i)","console.log('Hola desde MONDI AI');\nconst suma = (a,b) => a+b;\nconsole.log(suma(2,3));","#!/usr/bin/env bash\nset -e\necho 'Hola desde MONDI AI'\npwd\nls -la","git init\ngit add .\ngit commit -m \"Primer cambio\"","uname -a\nwhoami\npwd\ndf -h"};
 new AlertDialog.Builder(this).setTitle("Programación y Linux").setItems(names,(dialog,index)->{
 String content=scripts[index];
 new AlertDialog.Builder(this).setTitle(names[index]).setMessage(content)
 .setPositiveButton("Copiar",(d,w)->{
 android.content.ClipboardManager cb=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);
 cb.setPrimaryClip(ClipData.newPlainText(names[index],content));toast("Copiado");
 }).setNegativeButton("Cerrar",null).show();
 }).setNegativeButton("Cerrar",null).show();
 }
 void linuxSetup(){String guide="LINUX EN ANDROID\n\nMONDI usa Android como sistema principal. Para ejecutar herramientas GNU/Linux sin root puedes usar Termux y proot-distro.\n\n1. Instala Termux desde F-Droid.\n2. Abre Termux y ejecuta:\npkg update && pkg upgrade -y\npkg install proot-distro -y\nproot-distro install ubuntu\nproot-distro login ubuntu\n\nUbuntu corre en un contenedor de espacio de usuario; no da root real ni control ilimitado del móvil.\n\nPor seguridad, MONDI no ejecutará comandos Linux recibidos por la IA sin confirmación explícita.";new AlertDialog.Builder(this).setTitle("Linux / Ubuntu").setMessage(guide).setPositiveButton("Copiar comandos",(d,w)->{android.content.ClipboardManager cb=(android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE);cb.setPrimaryClip(ClipData.newPlainText("Ubuntu en Termux","pkg update && pkg upgrade -y\npkg install proot-distro -y\nproot-distro install ubuntu\nproot-distro login ubuntu"));toast("Comandos copiados");}).setNeutralButton("Abrir Termux",(d,w)->openTermux()).setNegativeButton("Cerrar",null).show();}
 void openTermux(){try{Intent i=getPackageManager().getLaunchIntentForPackage("com.termux");if(i!=null){startActivity(i);return;}}catch(Exception ignored){}new AlertDialog.Builder(this).setTitle("Linux con Termux").setMessage("Para Ubuntu o herramientas Linux completas, instala Termux desde F-Droid y configura proot-distro. MONDI AI no instala ni controla Termux automáticamente.").setPositiveButton("Abrir F-Droid",(d,w)->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://f-droid.org/packages/com.termux/")))).setNegativeButton("Cancelar",null).show();}
 void voice(){Intent i=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(RecognizerIntent.EXTRA_LANGUAGE,"es-ES");try{startActivityForResult(i,9);}catch(Exception e){toast("Reconocimiento de voz no disponible");}}
 void contacts(){Intent i=new Intent(Intent.ACTION_PICK,ContactsContract.CommonDataKinds.Phone.CONTENT_URI);try{startActivityForResult(i,10);}catch(Exception e){toast("No se puede abrir contactos");}}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==9){if(c==RESULT_OK&&d!=null){ArrayList<String> a=d.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS);if(a!=null&&!a.isEmpty()){input.setText(a.get(0));if(voiceSend)send();}}voiceSend=false;}else if(r==10&&c==RESULT_OK&&d!=null&&d.getData()!=null){try(Cursor cursor=getContentResolver().query(d.getData(),new String[]{ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,ContactsContract.CommonDataKinds.Phone.NUMBER},null,null,null)){if(cursor!=null&&cursor.moveToFirst()){String name=cursor.getString(0),number=cursor.getString(1);input.setText(number);append("Contacto seleccionado: "+name+" ("+number+")");}}catch(Exception e){toast("No se pudo leer el contacto seleccionado");}}else if(r==11&&c==RESULT_OK){if(android.os.Build.VERSION.SDK_INT<26||getPackageManager().canRequestPackageInstalls())checkUpdates();else toast("Autoriza la instalación de MONDI AI para continuar.");}}
 protected void onDestroy(){cancelRequested=true;HttpURLConnection c=activeConnection;if(c!=null)c.disconnect();if(tts!=null)tts.shutdown();super.onDestroy();}
